def crack_password(password):
    """
    Cracks a password by iterating through the dictionary and checking if the password matches the dictionary's key.
    """
    dictionary = {
        "abcdefghijklmnopqrstuvwxyz": "abcdefghijklmnopqrstuvwxyz",
        "0123456789": "0123456789",
        "!@#$%^&*()_+-=:;<>?,./"
